import{c as r,Q as d,j as o,m as n}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"项目管理","description":"","frontmatter":{"title":"项目管理"},"headers":[],"relativePath":"综合知识/项目管理.md","filePath":"综合知识/项目管理.md","lastUpdated":null}'),a={name:"综合知识/项目管理.md"};function s(e,t,h,g,l,i){return d(),o("div",null,[...t[0]||(t[0]=[n('<p>稍后整理</p><p>部分内容，看是在 <a href="/arch-exam/综合知识/软件工程/">架构师-备考 软件工程</a> 里面，待同步迁移一下。</p><h3 id="进度管理" tabindex="-1">进度管理 <a class="header-anchor" href="#进度管理" aria-label="Permalink to &quot;进度管理&quot;">​</a></h3><blockquote><p>进度管理六过程</p></blockquote><p>活动定义 → 活动排序 → 活动资源估算 → 活动历时估算 → 进度计划编制 → 进度控制。</p><h4 id="wbs" tabindex="-1">WBS <a class="header-anchor" href="#wbs" aria-label="Permalink to &quot;WBS&quot;">​</a></h4><p>软件项目往往是比较大而复杂的，往往需要进行层层分解，将大的任务分解成一个个的单一小任务进行处理。</p><p>工作分解结构(WBS)如图所示，就是把一个项目，按一定的原则分解成任务，任务再分解成一项项工作，再把一项项工作分配到每个人的日常活动中，直到分解不下去为止。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260518004120.png" alt="image.png"></p><p>WBS常见的分解方式包括：按产品的物理结构分解、按产品或项目的功能分解、按照实施过程分解、按照项目的实施单位分解、按照项目的目标分解、按部分或职能进行分解等。</p><p>不管采用哪种分解方式，最终都要满足以下对任务分解的基本要求。</p><ul><li>(1)WBS的工作包是可控和可管理的，不能过于复杂。</li><li>(2)任务分解也不能过细，一般原则WBS的树形结构不超过6层。</li><li>(3)每个工作包要有一个交付成果。</li><li>(4)每个任务必须有明确定义的完成标准。</li><li>(5)WBS必须有利于责任分配。</li></ul><h4 id="图形描述方法-gantt-图-vs-pert-图" tabindex="-1">图形描述方法 Gantt 图 vs PERT 图 <a class="header-anchor" href="#图形描述方法-gantt-图-vs-pert-图" aria-label="Permalink to &quot;图形描述方法 Gantt 图 vs PERT 图&quot;">​</a></h4><p>进度安排的常用图形描述方法有Gant图（甘特图）和项目计划评审技术(Program Evaluation&amp;Review Technique,PERT)图。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260518004245.png" alt="image.png"></p><hr><table tabindex="0"><thead><tr><th>对比</th><th>Gantt 图（甘特图）</th><th>PERT 图</th></tr></thead><tbody><tr><td><strong>反映并行关系</strong></td><td>能</td><td>不能</td></tr><tr><td><strong>反映依赖关系</strong></td><td>不能</td><td>能</td></tr></tbody></table><hr><h3 id="关键路径法-cpm" tabindex="-1">关键路径法（CPM） <a class="header-anchor" href="#关键路径法-cpm" aria-label="Permalink to &quot;关键路径法（CPM）&quot;">​</a></h3><blockquote><p>关键路径：项目的<strong>最短工期</strong>，但却是从开始到结束<strong>时间最长的路径</strong>。关键路径可能不止一条且会动态变化。关键活动：最早开始时间 = 最晚开始时间。</p></blockquote><p><strong>四个关键时间：</strong></p><table tabindex="0"><thead><tr><th>时间</th><th>全称</th><th>计算</th></tr></thead><tbody><tr><td><strong>ES</strong>（最早开始）</td><td>Earliest Start</td><td>顺推：所有前置活动 EF 的<strong>最大值</strong></td></tr><tr><td><strong>EF</strong>（最早完成）</td><td>Earliest Finish</td><td><strong>EF = ES + 工期</strong></td></tr><tr><td><strong>LF</strong>（最迟完成）</td><td>Latest Finish</td><td>逆推：所有后续活动 LS 的<strong>最小值</strong></td></tr><tr><td><strong>LS</strong>（最迟开始）</td><td>Latest Start</td><td><strong>LS = LF - 工期</strong></td></tr></tbody></table><p><strong>浮动时间：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>公式</th><th>说明</th></tr></thead><tbody><tr><td><strong>总浮动时间</strong></td><td>LS - ES 或 LF - EF</td><td>不延误项目完工时间的前提下可推迟的时间量</td></tr><tr><td><strong>自由浮动时间</strong></td><td>紧后活动 ES 的最小值 - 本活动 EF</td><td>不延误任何紧后活动最早开始时间</td></tr></tbody></table><blockquote><p>关键活动的总浮动时间为<strong>零</strong>。</p></blockquote><hr><p>最早开始时间 - 最迟开始时间</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260518004449.png" alt="image.png"></p><hr><h3 id="软件配置管理" tabindex="-1">软件配置管理 <a class="header-anchor" href="#软件配置管理" aria-label="Permalink to &quot;软件配置管理&quot;">​</a></h3><blockquote><p>配置管理目的：在整个生命周期中<strong>系统地控制配置变更</strong>，维持配置的完整性和可跟踪性。</p></blockquote><p><strong>六大活动</strong>：制订配置管理计划 → 配置标识 → 配置控制 → 配置状态报告 → 配置审计 → 发布管理和交付。</p><p><strong>配置项</strong>：为配置管理设计的硬件/软件或其集合。典型：项目计划书、需求文档、设计文档、源代码、可执行代码、测试用例、运行数据。<strong>经评审和检查通过后</strong>进入配置管理。</p><p><strong>配置项分类：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>内容</th><th>权限</th></tr></thead><tbody><tr><td><strong>基线配置项</strong></td><td>设计文档、源程序等</td><td>向开发人员开放读取</td></tr><tr><td><strong>非基线配置项</strong></td><td>项目计划、报告等</td><td>向 PM、CCB 及相关人员开放</td></tr></tbody></table><blockquote><p>所有配置项操作权限由 <strong>CMO（配置管理员）</strong> 严格管理。</p></blockquote><p><strong>配置项三种状态：</strong></p><table tabindex="0"><thead><tr><th>状态</th><th>触发条件</th><th>版本号格式</th></tr></thead><tbody><tr><td><strong>草稿</strong></td><td>刚建立</td><td><strong>0.YZ</strong>（YZ 递增）</td></tr><tr><td><strong>正式</strong></td><td>通过评审</td><td><strong>X.Y</strong>（第一次为 1.0）</td></tr><tr><td><strong>修改</strong></td><td>更改配置项</td><td><strong>X.YZ</strong>（修改时只增大 Z，完成后 Z=0，增大 XY）</td></tr><tr><td><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260518004556.png" alt="image.png"></td><td></td><td></td></tr></tbody></table><hr><p>其他</p><ul><li>配置项版本号</li><li>配置项版本管理</li><li>配置基线</li></ul><h3 id="质量管理" tabindex="-1">质量管理 <a class="header-anchor" href="#质量管理" aria-label="Permalink to &quot;质量管理&quot;">​</a></h3><blockquote><p>质量是软件产品满足明确（基本需求）或隐含（期望需求）要求的能力。</p></blockquote><table tabindex="0"><thead><tr><th>过程</th><th>说明</th></tr></thead><tbody><tr><td><strong>质量规划</strong></td><td>识别质量要求和标准，书面描述如何达到</td></tr><tr><td><strong>质量保证</strong></td><td>每隔一定时间通过<strong>质量审计（软件评审）和过程分析</strong>来保证</td></tr><tr><td><strong>质量控制</strong></td><td><strong>实时监控</strong>具体结果，判断是否符合质量标准，消除问题原因</td></tr></tbody></table><h3 id="风险管理" tabindex="-1">风险管理 <a class="header-anchor" href="#风险管理" aria-label="Permalink to &quot;风险管理&quot;">​</a></h3><blockquote><p>风险管理能<strong>避开不利条件、减少损失</strong>，但<strong>完全避开或消除风险是不可能的</strong>。</p></blockquote><p><strong>六大过程：</strong></p><table tabindex="0"><thead><tr><th>过程</th><th>内容</th></tr></thead><tbody><tr><td>风险管理计划编制</td><td>安排如何实施风险管理</td></tr><tr><td><strong>风险识别</strong></td><td>识别已知和可预测风险，形成<strong>风险列表</strong></td></tr><tr><td>风险定性分析</td><td>排序、确定可能性和影响、优先级、类型</td></tr><tr><td>风险定量分析</td><td>灵敏度分析、期望货币价值分析、决策树分析、蒙特卡罗模拟</td></tr><tr><td>风险应对计划</td><td>消极风险（避免/转移/减轻）；积极风险（开拓/分享/强大）</td></tr><tr><td>风险监控</td><td>监控执行、检测残余风险、识别新风险</td></tr></tbody></table><p><strong>宏观三类风险：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>威胁对象</th><th>示例</th></tr></thead><tbody><tr><td><strong>项目风险</strong></td><td>项目计划</td><td>预算、进度、人员、资源、用户需求问题</td></tr><tr><td><strong>技术风险</strong></td><td>质量和交付时间</td><td>设计/实现/接口问题、规格说明多义性、技术不确定性</td></tr><tr><td><strong>商业风险</strong></td><td>系统生存能力</td><td>市场风险、策略风险、销售风险、管理风险、预算风险</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：「仅根据风险产生的后果来对风险排优先级」— 错！风险优先级需综合考虑<strong>概率和影响</strong>。<br> ⚠️ 风险定义：不确定的事件或条件，可能对项目目标产生<strong>正面或负面</strong>影响（不只是负面）。</p></blockquote><hr><h3 id="成本管理" tabindex="-1">成本管理 ？ <a class="header-anchor" href="#成本管理" aria-label="Permalink to &quot;成本管理 ？&quot;">​</a></h3><p>这部分属于哪里？？</p><p><strong>成本按性态分类：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>固定成本</strong></td><td>不随业务量变化</td><td>固定资产折旧费、房屋租金</td></tr><tr><td style="text-align:left;"><strong>变动成本</strong></td><td>随业务量变化</td><td>外包费用、直接材料费</td></tr><tr><td style="text-align:left;"><strong>混合成本</strong></td><td>兼有两者特征</td><td>技术开发经费</td></tr></tbody></table><hr><h3 id="dcmm-数据管理能力成熟度" tabindex="-1">DCMM 数据管理能力成熟度 <a class="header-anchor" href="#dcmm-数据管理能力成熟度" aria-label="Permalink to &quot;DCMM 数据管理能力成熟度&quot;">​</a></h3><p>同上。。</p><blockquote><p>🎯 一句话结论：DCMM 将组织数据管理能力划分为 <strong>8 个能力域</strong>。</p></blockquote><p>8域：数据战略 → 数据治理 → 数据架构 → 数据标准 → 数据质量 → 数据安全 → <strong>数据应用</strong> → <strong>数据生存周期</strong></p>',61)])])}const c=r(a,[["render",s]]);export{b as __pageData,c as default};
